def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def = sum(1 for a in opp if a == 'D')
    opp_def_rate = opp_def / n

    if opp_def_rate > 0.7:
        return 'D'

    # Check if opponent is exploitable: we defected and they didn't retaliate, then cooperated again.
    for i in range(n - 1):
        if my[i] == 'D' and opp[i] == 'C' and opp[i + 1] == 'C':
            return 'D'

    # Check for alternating defection pattern: opponent switches C->D while we cooperate.
    switches = 0
    for i in range(1, n):
        if my[i - 1] == 'C' and opp[i - 1] == 'C' and opp[i] == 'D':
            switches += 1
    if switches >= 2:
        return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        if last_me == 'D':
            consec_dd = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    consec_dd += 1
                else:
                    break
            if consec_dd >= 2:
                return 'C'
            return 'D'
        else:
            if opp_def_rate < 0.3:
                return 'C'
            else:
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
    else:
        if last_me == 'D':
            return 'C'
        else:
            consec_cc = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'C' and opp[i] == 'C':
                    consec_cc += 1
                else:
                    break
            if consec_cc >= 12 and n < 90:
                recent_len = min(20, n)
                recent_opp_def = sum(1 for a in opp[-recent_len:] if a == 'D')
                recent_my_def = sum(1 for a in my[-recent_len:] if a == 'D')
                if recent_opp_def / recent_len < 0.1 and recent_my_def == 0:
                    return 'D'
            return 'C'
